j(node, bucket) {
        // DFS
        if (!node) {
            return;
        }
        if (node.left) {
            this.j(node.left, bucket);
        }
        if (node.value) {
            bucket.push([node.key, node.value]);
        }
        if (node.mid) {
            this.j(node.mid, bucket);
        }
        if (node.right) {
            this.j(node.right, bucket);
        }
    }
